<script setup>
import { useForm, usePage } from '@inertiajs/vue3';
import PublicLayout from '../../../Layouts/PublicLayout.vue';
import AdminQuickLinks from '../../../Components/AdminQuickLinks.vue';
import { Mail, Send, Download, Users } from 'lucide-vue-next';
const props = defineProps({ subscribers: { type: Object, default: () => ({ data: [], links: [] }) }, activeCount: { type: Number, default: 0 }, unsubscribedCount: { type: Number, default: 0 } });
const page = usePage();
const form = useForm({ subject: '', message: '' });
const send = () => { if (confirm(`Send this email to ${props.activeCount} active subscribers?`)) form.post('/admin/newsletter/send', { preserveScroll: true, onSuccess: () => form.reset() }); };
</script>
<template>
<PublicLayout>
<section class="bg-[#00351F]"><div class="mx-auto max-w-[1400px] px-5 py-10 lg:px-8"><p class="text-xs font-bold uppercase tracking-[.22em] text-[#D4A72C]">Super Admin</p><h1 class="mt-2 flex items-center gap-3 text-3xl font-extrabold text-white"><Mail :size="28"/> Newsletter Management</h1><p class="mt-2 text-sm text-white/75">Manage subscribers and send email updates to the BBHS mailing list.</p></div><AdminQuickLinks/></section>
<section class="bg-[#F7F9F7] py-10"><div class="mx-auto max-w-[1400px] space-y-6 px-5 lg:px-8">
<div v-if="page.props.flash?.success" class="rounded-lg bg-green-50 p-4 text-sm text-green-800">{{ page.props.flash.success }}</div>
<div class="grid gap-4 sm:grid-cols-3"><div class="rounded-xl border bg-white p-5"><p class="text-sm text-gray-500">Active subscribers</p><p class="mt-2 text-3xl font-extrabold text-[#006B3C]">{{ activeCount }}</p></div><div class="rounded-xl border bg-white p-5"><p class="text-sm text-gray-500">Unsubscribed</p><p class="mt-2 text-3xl font-extrabold text-gray-700">{{ unsubscribedCount }}</p></div><div class="flex items-center rounded-xl border bg-white p-5"><a href="/admin/newsletter/export" class="inline-flex items-center gap-2 rounded-lg bg-[#006B3C] px-4 py-3 text-sm font-bold text-white"><Download :size="16"/> Export subscriber CSV</a></div></div>
<div class="grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><form @submit.prevent="send" class="space-y-4 rounded-2xl border bg-white p-6 shadow-sm"><div><h2 class="text-lg font-extrabold text-[#00351F]">Send an email update</h2><p class="mt-1 text-xs text-gray-500">This sends to active subscribers only. Unsubscribed addresses are excluded.</p></div><div><label class="mb-1 block text-sm font-bold">Subject</label><input v-model="form.subject" required maxlength="180" class="w-full rounded-lg border-gray-300"/><p v-if="form.errors.subject" class="mt-1 text-xs text-red-600">{{ form.errors.subject }}</p></div><div><label class="mb-1 block text-sm font-bold">Message</label><textarea v-model="form.message" required rows="9" maxlength="12000" class="w-full rounded-lg border-gray-300" placeholder="Write your BBHS update here..."></textarea><p v-if="form.errors.message" class="mt-1 text-xs text-red-600">{{ form.errors.message }}</p></div><p class="rounded-lg bg-amber-50 p-3 text-xs leading-5 text-amber-800">Ensure your SMTP settings are working before sending. A personalised unsubscribe link is automatically appended to every email. For a large mailing list, use a queued mail service to avoid request timeouts.</p><button :disabled="form.processing || activeCount === 0" class="inline-flex items-center gap-2 rounded-lg bg-[#006B3C] px-5 py-3 text-sm font-bold text-white disabled:opacity-50"><Send :size="16"/>{{ form.processing ? 'SENDING...' : `SEND TO ${activeCount} SUBSCRIBERS` }}</button></form>
<div class="overflow-hidden rounded-2xl border bg-white shadow-sm"><div class="flex items-center justify-between border-b p-5"><div><h2 class="font-extrabold text-[#00351F]">Subscriber list</h2><p class="text-xs text-gray-500">Most recent subscriptions</p></div><Users class="text-[#006B3C]"/></div><div v-if="!subscribers.data?.length" class="p-6 text-sm text-gray-500">No newsletter subscribers yet.</div><div v-else class="divide-y"> <div v-for="subscriber in subscribers.data" :key="subscriber.id" class="flex items-center justify-between gap-3 p-4"><div class="min-w-0"><p class="truncate text-sm font-semibold text-gray-800">{{ subscriber.email }}</p><p class="mt-1 text-xs text-gray-500">{{ subscriber.subscribed_at || 'Date unavailable' }}</p></div><span :class="subscriber.unsubscribed_at ? 'bg-gray-100 text-gray-600' : 'bg-green-50 text-green-700'" class="shrink-0 rounded-full px-2.5 py-1 text-[10px] font-bold">{{ subscriber.unsubscribed_at ? 'UNSUBSCRIBED' : 'ACTIVE' }}</span></div></div><div v-if="subscribers.links?.length" class="flex flex-wrap gap-2 border-t p-4"><a v-for="link in subscribers.links" :key="link.label" :href="link.url || '# '" v-html="link.label" :class="link.active ? 'bg-[#006B3C] text-white' : 'bg-gray-100 text-gray-700'" class="rounded px-3 py-2 text-xs"/></div></div>
</div></div></section>
</PublicLayout>
</template>
